// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {ReentrancyDAO} from "../src/ReentrancyDAO.sol";

contract InvMutTest is Test {
    ReentrancyDAO c;
    function setUp() public { c = new ReentrancyDAO(); }
    function testFuzz_property(uint256 amount, address actor) public {
        vm.assume(actor.code.length == 0);
        vm.assume(actor != address(c));
        amount = bound(amount, 1, type(uint128).max);

        vm.deal(actor, amount);
        vm.prank(actor);
        c.deposit{value: amount}();

        // first withdrawal from a plain EOA must succeed (call to EOA always succeeds)
        vm.prank(actor);
        bool first;
        try c.withdrawAll() { first = true; } catch { first = false; }
        assertTrue(first, "first withdrawAll must succeed");

        // RULE: after the first withdrawal, the credit is cleared, so a second
        // withdrawAll from the same actor must succeed as a no-op.
        vm.prank(actor);
        bool second;
        try c.withdrawAll() { second = true; } catch { second = false; }
        assertTrue(second, "second withdrawAll must succeed after credit cleared");
    }
}
